import { expect } from "chai";
import { network } from "hardhat";
import { readFileSync } from "node:fs";
import type { Poseidon1Harness } from "../types/ethers-contracts/index.js";

const { ethers } = await network.create();

const P = 0x7ffffffffffffffffffffffffffffffe0673ddf29e9b5547c000000000000001n;

/** The limit on the size of deployed code (EIP-170). */
const MAX_CODE_SIZE = 24576;

/** The state widths of the permutation libraries. */
const WIDTHS = [3, 4, 5];

/** A permutation test case generated by `tools/poseidon1` with the `starkom-poseidon` crate. */
interface PermutationCase {
  width: number;
  input: string[];
  output: string[];
}

/** A sponge test case generated by `tools/poseidon1` with the `starkom-poseidon` crate. */
interface HashCase {
  width: number;
  dst: string[];
  inputs: string[];
  output: string[];
}

const vectors: { permutations: PermutationCase[]; hashes: HashCase[] } = JSON.parse(
  readFileSync(new URL("./vectors/poseidon1.json", import.meta.url), "utf8"),
);

// From the `test_permutation_t*_x5` tests of the `starkom-poseidon` crate: the permutations of
// [0, 1, ..., T - 1].
const RUST_PERMUTATIONS: Record<number, bigint[]> = {
  3: [
    0x7b68dcd80fa751ee8f2d76043bfd92c685601c79189393fc76e03c5214eed32bn,
    0x0fbcb5720b463bf7e2ccabf373e77d2c10d27e6549f34cfa33eb2d06ea8b900an,
    0x26e03abfcc62da0101516b07aede8bc676a10c47299a57bedc6d9fe80484f3dan,
  ],
  4: [
    0x12dde8a4c46760e349670d241e36ca7abacc991233039f8deaf6c58ce2230ef6n,
    0x61e95d9456e9223b4d7926dabae10009da2b6fb9134ade8405f6ef1424e66aa1n,
    0x2fcce25ab9efb3e26276f3b3aff1e02cdf82df48ce8d3eadbff900cfe015775bn,
    0x2580707d57a8c1c0cad368e8d5705ffd96f269d66e1cd6f1433f93a3c66d9bf8n,
  ],
  5: [
    0x14bbfce637c6a0038f076b56a2ac76bc3f6363a3cef7f1d97acaf94a14ef724dn,
    0x68abac631a3a117f229d137ffe2bf14d6673495aa3ca484864a713b3b6349369n,
    0x4a49e726e6c3d0848378d6897b8f67f23ce2ef949ed0ca4a1df255925f8e4bb7n,
    0x521164b1b6acd0b5fe257d580014ff766ae51b2ed3e2c400c9e748ec864a9dd0n,
    0x0273a96bdf343289e82b28464897a8a5e3bb02a1ce52fd36ed32862315ccd71bn,
  ],
};

/** Returns [0, 1, ..., width - 1]. */
function counting(width: number): bigint[] {
  return Array.from({ length: width }, (_, i) => BigInt(i));
}

describe("Poseidon1", function () {
  let harness: Poseidon1Harness;
  const libraries: Record<string, string> = {};

  before(async function () {
    for (const width of WIDTHS) {
      const library = await ethers.deployContract(`Poseidon1T${width}X5`);
      libraries[`Poseidon1T${width}X5`] = await library.getAddress();
    }
    harness = await ethers.deployContract("Poseidon1Harness", [], { libraries });
  });

  function permute(width: number, state: bigint[]): Promise<bigint[]> {
    return harness.getFunction(`permuteT${width}X5`)(state);
  }

  function hash(width: number, dst: bigint[], inputs: bigint[]): Promise<bigint[]> {
    return harness.getFunction(`hashT${width}X5`)(dst, inputs);
  }

  function hash0(width: number, dst: bigint[], inputs: bigint[]): Promise<bigint> {
    return harness.getFunction(`hash0T${width}X5`)(dst, inputs);
  }

  describe("permutation libraries", function () {
    for (const width of WIDTHS) {
      it(`Poseidon1T${width}X5 fits in the contract size limit`, async function () {
        const code = await ethers.provider.getCode(libraries[`Poseidon1T${width}X5`]);
        expect(ethers.dataLength(code)).to.be.lessThanOrEqual(MAX_CODE_SIZE);
      });

      it(`Poseidon1T${width}X5 matches the Rust unit test`, async function () {
        expect(await permute(width, counting(width))).to.deep.equal(RUST_PERMUTATIONS[width]);
      });

      it(`Poseidon1T${width}X5 reduces non-canonical inputs`, async function () {
        const state = counting(width).map((value) => value + P);
        expect(await permute(width, state)).to.deep.equal(RUST_PERMUTATIONS[width]);
      });
    }

    for (const { width, input, output } of vectors.permutations) {
      it(`Poseidon1T${width}X5 permutes [${input[0].slice(0, 10)}..., ...]`, async function () {
        expect(await permute(width, input.map(BigInt))).to.deep.equal(output.map(BigInt));
      });
    }
  });

  describe("sponge", function () {
    for (const { width, dst, inputs, output } of vectors.hashes) {
      const description =
        `hashT${width}X5 with capacity ${dst.length} and ${inputs.length} inputs ` +
        `[${inputs[0].slice(0, 10)}..., ...]`;

      it(description, async function () {
        expect(await hash(width, dst.map(BigInt), inputs.map(BigInt))).to.deep.equal(
          output.map(BigInt),
        );
      });

      it(`hash0T${width}X5 with the same arguments`, async function () {
        expect(await hash0(width, dst.map(BigInt), inputs.map(BigInt))).to.equal(BigInt(output[0]));
      });
    }

    // Same as the `test_capacity_dst_t*` tests of the `starkom-poseidon` crate: with the tag
    // T - 1 and the inputs [0, 1, ..., T - 2] the state is [0, 1, ..., T - 1] when it's permuted.
    for (const width of WIDTHS) {
      it(`hashT${width}X5 initializes the capacity with the tags`, async function () {
        const inputs = counting(width - 1);
        expect(await hash(width, [BigInt(width - 1)], inputs)).to.deep.equal(
          RUST_PERMUTATIONS[width].slice(0, width - 1),
        );
      });
    }

    for (const width of WIDTHS) {
      it(`hashT${width}X5 rejects empty inputs`, async function () {
        await expect(hash(width, [0n], [])).to.be.revertedWithCustomError(harness, "EmptyInput");
      });

      it(`hashT${width}X5 rejects a capacity equal to the width`, async function () {
        await expect(hash(width, new Array(width).fill(0n), [1n]))
          .to.be.revertedWithCustomError(harness, "InvalidCapacity")
          .withArgs(width, width);
      });

      it(`hashT${width}X5 rejects a capacity larger than the width`, async function () {
        await expect(hash(width, new Array(width + 1).fill(0n), [1n]))
          .to.be.revertedWithCustomError(harness, "InvalidCapacity")
          .withArgs(width + 1, width);
      });

      it(`hashT${width}X5 rejects a non-canonical input`, async function () {
        await expect(hash(width, [0n], [1n, P]))
          .to.be.revertedWithCustomError(harness, "NonCanonicalInput")
          .withArgs(P);
      });

      it(`hashT${width}X5 rejects a non-canonical tag`, async function () {
        await expect(hash(width, [P + 1n], [1n]))
          .to.be.revertedWithCustomError(harness, "NonCanonicalInput")
          .withArgs(P + 1n);
      });
    }
  });
});
